{"input_json_path": "test_single.json", "output_json_path": "consolidated_nitrides_final.json", "custom_code": "
import json
import glob

# Start with the input data
filtered_data = []

# Get all polymorph JSON files
import os
polymorph_files = []
try:
    for filename in os.listdir('polymorph_data'):
        if filename.endswith('_polymorphs.json'):
            polymorph_files.append(os.path.join('polymorph_data', filename))
except:
    pass

# Read and combine all files
for filepath in polymorph_files:
    try:
        with open(filepath, 'r') as f:
            comp_data = json.load(f)
            # Extract composition name from filename
            comp_name = os.path.basename(filepath).replace('_polymorphs.json', '')
            # Add composition info to each polymorph
            for polymorph in comp_data:
                polymorph['composition'] = comp_name
            filtered_data.extend(comp_data)
    except Exception as e:
        pass
"}

